"""Whole-file explanations of binary search and binary GCD contracts."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='알고리즘 · 탐색·정수론·인터페이스',
                     sections=sections, questions=questions))


add('lib/bsearch.c', '이진 탐색 공개 함수 전체: 정렬 계약과 인라인 구현 연결',
    '공개 bsearch 심벌과 헤더의 실제 탐색 루프를 구분합니다.',
    'bsearch는 key, base, num, size, cmp를 그대로 __inline_bsearch에 전달하고 그 반환 포인터를 돌려줍니다. 공개 함수 본문에 별도 탐색 상태나 할당은 없습니다.',
    '배열은 비교 함수와 일치하는 오름차순이어야 합니다. 결과는 기존 원소 주소 또는 NULL이며 새 객체가 아닙니다.',
    [('파일 전체 구성', 'SPDX와 저작권, export/bsearch/kprobes 헤더, 사용 계약 주석, 전달 함수, EXPORT_SYMBOL과 NOKPROBE_SYMBOL이 전부입니다. NOKPROBE_SYMBOL은 이 심벌의 kprobe 제한을 표시하며 함수의 정렬 검사나 메모리 검증을 추가하지 않습니다.'),
     ('비교 계약', 'cmp의 첫 인자는 검색 키이고 둘째는 원소 주소입니다. 키와 원소는 서로 다른 자료형이어도 비교 함수가 이를 올바르게 해석하면 됩니다. 예컨대 문자열 키와 구조체의 name 필드를 비교할 수 있습니다. 같은 타입일 때 sort와 비교 함수를 공유할 수 있다는 주석은 다른 타입도 무조건 같은 comparator로 정렬하라는 뜻이 아닙니다.'),
     ('소유권과 복잡도', '반환 주소는 입력 배열 내부이므로 배열의 수명과 동시 수정 규칙을 따라야 합니다. 이 파일은 배열을 정렬하거나 잠그지 않습니다. 헤더 알고리즘의 비교 횟수는 O(log n), 추가 공간은 O(1)이지만 한 번의 문자열 비교 비용은 별도로 곱해집니다. 중복 키의 첫 원소를 보장하지 않습니다.')],
    [('문자열 키로 구조체 배열을 탐색할 수 있는가?', '가능하다. cmp가 키와 원소의 서로 다른 타입을 처리해야 한다', '불가능하다. 두 포인터의 대상 타입이 항상 같아야 한다', '인터페이스는 const void* 두 개를 받고 주석도 이종 키를 명시합니다. cmp(key, element)의 인자 순서를 지켜야 합니다.'),
     ('성공한 bsearch의 반환값은 누가 할당한 메모리인가?', '호출자가 전달한 기존 배열 안의 원소 주소다', 'bsearch가 새로 할당한 복사 객체다', '공개 함수는 헤더의 결과만 반환하며 할당 경로가 없습니다. 결과만 별도로 해제하는 API가 아닙니다.')])

add('include/linux/bsearch.h', '이진 탐색 루프 전체: 후보 개수 불변식과 중복 키',
    'base와 num이 나타내는 후보 구간을 매 반복 절반으로 줄이는 구현입니다.',
    'pivot은 base+(num>>1)*size입니다. cmp가 0이면 반환하고 양수이면 base를 pivot 다음으로 옮기며 num을 하나 줄입니다. 마지막 num>>=1이 다음 후보 수를 만듭니다.',
    'size가 실제 원소 간격과 같고 모든 주소 계산이 유효해야 합니다. GNU C의 void* 산술을 쓰며 표준 C 이식 시 바이트 포인터 변환이 필요합니다.',
    [('파일 전체', 'include guard, linux/types.h, static __always_inline 구현, 공개 bsearch의 extern 선언으로 구성됩니다. 루프는 num>0일 때만 cmp를 호출합니다. num=0이면 base를 읽거나 cmp를 호출하지 않고 NULL을 반환합니다.'),
     ('짝수·홀수 구간 계산', 'num=6이면 pivot index는 3입니다. 왼쪽은 index0..2의 3개로 6>>1이며 오른쪽은 index4..5의 2개로 (6-1)>>1입니다. num=5의 pivot은2이고 양쪽 모두2개입니다. 양수 분기의 num--가 짝수 구간에서 오른쪽 후보 수를 맞춥니다.'),
     ('정렬과 종료 불변식', '정렬 및 comparator의 순서 일관성이 있어야 버린 구간에 답이 없다고 말할 수 있습니다. num은 성공하지 않은 각 반복에서 줄어 0이 됩니다. 반환은 처음 만난 동등 원소이므로 lower_bound처럼 중복의 왼쪽 끝을 찾지 않습니다.'),
     ('CS와 안전 경계', 'O(log n)은 비교 횟수입니다. cmp 비용이 문자열 길이 m에 비례하면 최악 비용에 m이 포함됩니다. 반환할 때 const를 제거한 포인터를 주어도 읽기 전용 배열이 쓰기 가능한 메모리로 바뀌지는 않습니다. size·곱셈 오버플로·객체 수명·정렬을 이 함수가 검증하지 않습니다.')],
    [('후보 6개에서 키가 pivot보다 크면 다음 후보 개수는?', '2개', '3개', 'pivot은 index3이고 오른쪽은4,5입니다. num을 먼저5로 줄인 다음 오른쪽 시프트하여2가 됩니다.'),
     ('동일한 키가 여러 개이면 항상 첫 번째 것을 반환하는가?', '아니다. 탐색 도중 먼저 만난 같은 원소를 반환한다', '그렇다. 같은 키라도 왼쪽 탐색을 계속한다', 'result==0 분기가 즉시 반환하므로 더 작은 인덱스를 찾지 않습니다.'),
     ('num=0일 때 cmp 호출 횟수는?', '0회', '1회', 'while(num>0)에 들어가지 않습니다. NULL 반환은 비교할 원소가 없다는 결과입니다.')])

add('lib/math/gcd.c', '최대공약수 전체: 두 가지 이진 GCD와 공통 2의 인수',
    '나눗셈 기반 유클리드 알고리즘과 다른 비트·뺄셈 구현을 비교합니다.',
    'r=a|b로 공통 2의 인수를 추적합니다. CONFIG_CPU_NO_EFFICIENT_FFS 설정에 따라 최하위 1비트 위치를 이용하는 구현과 반복 시프트 구현 중 하나를 컴파일합니다.',
    '입출력은 unsigned long이며 gcd(a,0)=a, gcd(0,b)=b, gcd(0,0)=0을 반환합니다. 정수론적 정의와 API의 영 입력 규약을 구분합니다.',
    [('전체 파일과 분기', 'SPDX, kernel/gcd/export 헤더, 알고리즘 배경 주석, #if/#else의 두 gcd 정의와 GPL export가 전부입니다. 주석의 속도 비교는 구현 선택 배경이며 모든 현대 CPU와 입력에서의 성능 보장이 아닙니다.'),
     ('효율적인 ffs 경로', '처음 영 입력을 반환하므로 뒤의 __ffs에 0을 넘기지 않습니다. b와 a의 2 인수를 제거하여 홀수로 만들고 같은 값이면 공통 시프트를 복구합니다. 하나가1이면 r&-r을 반환합니다. 서로 다르면 큰 값에서 작은 값을 빼며 gcd를 보존합니다.'),
     ('반복 시프트 경로', 'r&=-r로 공통 2 인수에 해당하는 최하위 1비트를 남깁니다. b와 a를 r 위치의 비트가 켜질 때까지 옮깁니다. 같으면 a, 하나가r이면 r을 반환합니다. 차를 절반으로 옮긴 뒤 a&r 여부에 따라 b를 더하고 다시 절반으로 옮기는 최적화도 원본에 포함됩니다. 이 경로를 단순한 같은 루프의 함수명 치환으로 이해하면 안 됩니다.'),
     ('예제와 비트 연산', '48과18의 gcd는6입니다. a|b=50=110010₂라 최하위 1비트 값은2입니다. 홀수 부분의 gcd3에2를 복구하면6입니다. unsigned의 -r은 모듈러 산술이며 r&-r은 0이 아닌 r의 최하위 1비트를 분리합니다.'),
     ('연결되는 CS', 'gcd(a,b)=gcd(a-b,b), 공통 2 인수 분리, 종료를 위한 값 감소, 컴파일 시 알고리즘 선택을 학습합니다. 분기마다 반환이 같아야 하므로 테스트는 나머지 기반 독립 참조 구현과 두 설정을 비교하는 것이 유용합니다.')],
    [('gcd(48,18)의 결과와 공통 2의 인수는?', '결과6, 공통 2의 인수2', '결과2, 공통 2의 인수6', '최하위 비트 값2만으로 끝나지 않습니다. 홀수 부분의 공약수3도 복원해야 합니다.'),
     ('gcd(0,0)은 이 구현에서 무엇을 반환하는가?', '0', '항상 오류 코드를 반환한다', '초기 !a||!b 분기가 a|b를 반환하므로0입니다. 수학적 용어와 별도로 코드의 규약을 확인합니다.'),
     ('최적화 경로가 __ffs(0)을 처음부터 호출하는가?', '아니다. 영 입력은 초기 분기에서 반환한다', '그렇다. __ffs가 0도 처리한다고 가정한다', '영 입력을 먼저 배제하고 서로 같은 값도 뺄셈 전에 반환하여 필요한 비영 전제를 유지합니다.')])

add('include/linux/gcd.h', 'GCD 헤더 전체: 값 기반 함수와 컴파일러 속성',
    '짧은 선언 파일도 구현 파일과 별도로 API의 타입·속성을 읽습니다.',
    'gcd는 unsigned long 두 개를 받고 unsigned long을 반환하며 __attribute_const__가 붙습니다.',
    '실제 알고리즘은 lib/math/gcd.c에 있습니다. 이 선언은 오류 코드나 출력 포인터를 제공하지 않습니다.',
    [('파일 전체 구성', 'SPDX, _GCD_H include guard, compiler.h 포함, 단일 gcd 선언, #endif가 전부입니다. compiler.h는 함수 속성 매크로를 제공하는 연결점입니다.'),
     ('타입 계약', 'unsigned long의 폭은 대상 ABI에 의존합니다. 음수를 그대로 넘기면 unsigned 변환이 일어나므로 signed 정수 절댓값 GCD와 혼동하면 안 됩니다. 헤더에는 임의 정밀도나 u64 전용 타입이 없습니다.'),
     ('const 속성의 의미', '__attribute_const__는 함수 결과가 인자 값에 의존하고 관찰 가능한 부수효과가 없다는 최적화 계약입니다. 반환값을 const 변수로 만든다는 뜻도 컴파일 시 계산을 강제한다는 뜻도 아닙니다. 실제 영 입력 반환과 두 알고리즘 분기는 구현에서 확인합니다.')],
    [('__attribute_const__가 반환값 수정을 금지하는가?', '아니다. 호출 최적화에 쓰이는 함수의 효과·의존성 계약이다', '그렇다. 결과를 받은 변수는 수정할 수 없다', 'C 타입의 const 한정자가 아니라 함수 속성입니다. 결과를 일반 변수에 저장하여 수정할 수 있습니다.'),
     ('헤더만 보고 unsigned long을 항상64비트라고 가정할 수 있는가?', '없다. 대상 ABI의 타입 폭을 확인해야 한다', '있다. Linux 헤더의 long은 언제나64비트다', '함수는 고정 폭 u64가 아니라 unsigned long을 선언합니다. 대상 타입 폭이 표현 가능한 입력 범위를 결정합니다.')])

add('lib/math/lcm.c', '최소공배수 전체: 나누기 순서와 오버플로 한계',
    '수학적 항등식을 기계 정수로 구현할 때 남는 경계 조건을 읽습니다.',
    'lcm은 두 입력이 비영이면 (a/gcd(a,b))*b를 반환하고 하나라도0이면0입니다. lcm_not_zero는 lcm 결과가 비영이면 사용하고0이면 b가 비영일 때 b, 아니면 a를 반환합니다.',
    '먼저 나누면 a*b를 먼저 계산하는 것보다 중간 오버플로를 줄이지만 최종 곱이 unsigned long을 넘는 경우를 검출하지는 않습니다.',
    [('파일 전체', 'SPDX, compiler/gcd/export/lcm 헤더, lcm과 lcm_not_zero 두 함수 및 각 GPL export로 구성됩니다. 메모리 할당이나 루프는 없으며 비영 경로의 핵심 계산은 gcd에 위임됩니다.'),
     ('정상 예제', 'lcm(12,18)=(12/6)*18=36입니다. lcm(0,18)=0인 반면 lcm_not_zero(0,18)=18, lcm_not_zero(12,0)=12, 양쪽0이면0입니다. 이름에 not_zero가 있어도 무조건 비영이라는 의미가 아닙니다.'),
     ('오버플로와 대체 경로', 'unsigned 곱셈은 타입 폭으로 순환하며 오류 반환 장치가 없습니다. lcm_not_zero도 결과 l이0인지 검사할 뿐 입력 영 여부만 검사하지 않습니다. 그러므로 안전한 수학적 LCM 또는 checked arithmetic API로 오해하면 안 됩니다. 필요한 호출자는 곱의 표현 가능성을 따로 확인해야 합니다.'),
     ('GNU 확장과 CS', 'b ? : a는 GNU C의 생략된 가운데 피연산자 표현식으로 b가 참이면 b, 아니면 a입니다. 최대공약수와 최소공배수의 관계, 연산 순서, 고정 폭 정수, 특수값 대체 정책을 연결합니다.')],
    [('먼저 gcd로 나누면 모든 오버플로가 없어지는가?', '아니다. 최종 곱이 타입 범위를 넘을 수 있다', '그렇다. 어떤 입력도 정확한 수학적 LCM을 반환한다', '공통 인수를 먼저 줄여도 서로소인 큰 수의 곱은 표현 범위를 넘습니다. 소스에 overflow 검사나 넓은 결과 타입이 없습니다.'),
     ('lcm_not_zero(0,0)은?', '0', '1', 'lcm은0이고 마지막 b ? : a도0입니다. 함수 이름만으로 비영 후조건을 만들면 안 됩니다.'),
     ('lcm(12,18) 계산 순서는?', '12를 gcd6으로 나누고18을 곱한다', '12와18을 더하고 gcd6으로 나눈다', '소스 식 (a/gcd(a,b))*b에 따라2*18=36입니다.')])

add('include/linux/lcm.h', 'LCM 헤더 전체: 유사한 두 API의 별도 계약',
    '같은 인자·반환 타입을 가진 두 함수라도 영 입력의 의미가 다를 수 있습니다.',
    'lcm과 lcm_not_zero 모두 unsigned long 두 인자를 받고 같은 타입을 반환하며 __attribute_const__로 선언됩니다.',
    '호출 전에 필요한 것이 일반 LCM인지 영 입력의 다른 쪽 값 대체인지 구분합니다. 상세 반환 정책은 lib/math/lcm.c와 함께 읽습니다.',
    [('전체 파일', 'SPDX, _LCM_H guard, compiler.h, 두 함수 선언, #endif로 끝납니다. 구현·상수 표·동적 상태는 없습니다.'),
     ('타입과 효과', '두 함수 모두 값으로 입력을 전달하며 결과 저장소 포인터를 받지 않습니다. 속성은 값 기반 최적화 계약이며 범위 검사·오버플로 검출·예외 발생을 추가하지 않습니다.'),
     ('호출자 후조건', 'not_zero 이름에도 두 인자가 모두0이면 결과0입니다. 구현의 fallback 정책과 수학적 LCM을 구분하고, unsigned long 타입 범위 및 변환도 호출자 쪽에서 고려합니다. include guard는 한 번의 전처리 단위에서 중복 헤더 본문 처리를 막습니다.')],
    [('두 함수의 타입이 같으면 모든 입력에 결과도 같은가?', '아니다. 한쪽 입력이0이면 대체 정책이 다를 수 있다', '그렇다. C 선언이 같으면 동작도 같다', '함수 이름과 실제 구현의 계약이 다릅니다. lcm(0,18)=0, lcm_not_zero(0,18)=18입니다.'),
     ('이 헤더에 오버플로 오류를 전달하는 별도 출력 인자가 있는가?', '없다', '있다. 세 번째 인자가 오류 포인터다', '두 선언은 unsigned long 인자 두 개뿐입니다. 값 기반 선언 자체가 산술 오류 검사를 보장하지 않습니다.')])
